insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'ms_theatre3_v1'
from (values
('117.213.b.1.A',4,'After a rehearsal, an eighth grader judges whether her use of a remembered scent made her grieving character believable. She is evaluating her:','["use of sensory and emotional recall", "ticket sales", "parking plan", "lobby display"]'::jsonb,0,'Evaluating characterization means judging how well recall techniques worked.','original'),
('117.213.b.1.A',4,'A director tells an actor that her personal memory of fear came across as real but too quiet to read from the back row. The note evaluates her:','["lighting angle", "emotional recall", "costume fit", "program layout"]'::jsonb,1,'Feedback can judge how effectively recall was used.','original'),
('117.213.b.1.B',3,'An ensemble warm-up that includes vocal sirens, shoulder rolls and a focus game explores:','["ticket pricing", "scenery storage", "preparation techniques", "intermission length"]'::jsonb,2,'Preparation includes physical, vocal and mental warm-ups.','original'),
('117.213.b.1.B',3,'Practicing a monologue in short sections, then running it with a partner, is part of an actor''s:','["lighting plot", "set strike", "audience etiquette", "preparation process"]'::jsonb,3,'Rehearsal routines are preparation.','original'),
('117.213.b.1.C',3,'Without any props, an actor shows she is carrying a huge box up a flight of stairs. She is using:','["mime to define space", "a follow spot", "a prompt book", "a green screen"]'::jsonb,0,'Mime defines objects and space with the body.','original'),
('117.213.b.1.C',3,'A student creates a walk and posture to show an elderly character. She is creating:','["a program", "expressive movement to define a character", "a stage plan", "a budget"]'::jsonb,1,'Movement can define character age and personality.','original'),
('117.213.b.1.D',4,'A student explains that lower breath support and open throat settings help project the voice without strain. She understands:','["blocking notation", "lighting design", "mechanisms of vocal production", "costume repair"]'::jsonb,2,'Vocal production depends on breath, phonation and resonance.','original'),
('117.213.b.1.D',4,'Articulation exercises such as repeating crisp consonants improve an actor''s:','["costume weight", "prop storage", "stage lighting", "clarity of speech"]'::jsonb,3,'Articulation drills improve clear speech.','original'),
('117.213.b.1.E',3,'Applying theatrical vocabulary, a stage manager says ''Places'' to tell the cast to:','["get ready in their starting positions", "change costumes", "leave the theater", "go home"]'::jsonb,0,'''Places'' calls actors to starting positions.','original'),
('117.213.b.1.E',3,'When a director uses the term ''upstage,'' she is referring to:','["the left aisle", "the area farthest from the audience", "the balcony", "the area closest to the audience"]'::jsonb,1,'Upstage is away from the audience.','original'),
('117.213.b.1.F',4,'Exploring the form of a play, a student notices a subplot that runs alongside the main plot. This is a:','["stage direction", "prop list", "secondary storyline", "costume change"]'::jsonb,2,'A subplot supports or contrasts the main story.','original'),
('117.213.b.1.F',4,'Evaluating dramatic literature, a student asks whether the play''s rising action builds toward its:','["cast list", "curtain call", "audition", "climax"]'::jsonb,3,'Rising action builds toward the climax.','original'),
('117.213.b.2.A',2,'Before running a physical scene, the cast checks the floor for hazards. This shows safe use of the:','["body in rehearsal", "program", "ticket line", "parking lot"]'::jsonb,0,'Safety checks protect actors.','original'),
('117.213.b.2.A',3,'An actor protects her voice during a long performance run by:','["skipping warm-ups", "resting and staying hydrated between shows", "yelling backstage", "whispering throughout"]'::jsonb,1,'Voice care involves rest and water.','original'),
('117.213.b.2.B',3,'Using a familiar gesture, such as shrugging when unsure, helps an actor portray a character through:','["unusual props", "unknown cues", "familiar movements", "costume tags"]'::jsonb,2,'Familiar gestures make characters believable.','original'),
('117.213.b.2.B',3,'An actor portrays a character with short, clipped sentences and a stiff walk. She is portraying the character through:','["sound cues", "scenery", "lighting", "movement and dialogue"]'::jsonb,3,'Characters are shown through what they do and say.','original'),
('117.213.b.2.C',4,'In an improvised scene, two actors establish a conflict, build tension and reach a resolution. They are reflecting:','["dramatic structure", "program notes", "ticket sales", "lobby music"]'::jsonb,0,'Even improv follows dramatic structure.','original'),
('117.213.b.2.C',4,'A scripted scene and an improvised scene both create characters, dialogue and:','["no purpose", "actions that follow a structure", "no actions", "random noise"]'::jsonb,1,'Both forms rely on structure.','original'),
('117.213.b.2.D',3,'An actor expresses frustration through a tight voice and short words. She is using:','["a scene change", "a lighting cue", "effective voice", "unclear mumbling"]'::jsonb,2,'Voice choices express emotion.','original'),
('117.213.b.2.D',3,'Good diction in a large theater means the actor:','["speaks only to her partner", "whispers constantly", "mumbles", "speaks clearly so the back row understands"]'::jsonb,3,'Diction is clarity of speech.','original'),
('117.213.b.3.A',4,'A designer chooses cool blue lighting and soft music to establish a calm mood. She is selecting:','["technical elements to establish mood", "only a prop", "only a ticket", "only a costume"]'::jsonb,0,'Light and sound set mood.','original'),
('117.213.b.3.A',4,'To suggest the environment of a stormy night, a crew might use:','["bright sunny lighting", "thunder sound effects and flickering light", "birdsong", "quiet silence"]'::jsonb,1,'Technical elements suggest environment.','original'),
('117.213.b.3.B',3,'A student sketches a costume for a character and chooses colors that reflect the character''s mood. She is creating a:','["stage curtain only", "ticket", "theatrical element", "budget form"]'::jsonb,2,'Costumes are theatrical elements.','original'),
('117.213.b.3.B',3,'Painting a flat to look like a brick wall is a task for the:','["box office", "ushers", "audience", "scenic crew"]'::jsonb,3,'Scenery is built and painted by the scenic crew.','original'),
('117.213.b.3.C',3,'A director who resolves a conflict between two designers about lighting and costumes acts as a:','["problem solver", "ticket seller", "audience member", "stagehand only"]'::jsonb,0,'Directors solve problems among the team.','original'),
('117.213.b.3.C',3,'A director who creates a single vision combining acting, design and music acts as a:','["divider", "unifying force", "prompter only", "spectator"]'::jsonb,1,'The director unifies all elements.','original'),
('117.213.b.3.D',3,'Posting a rehearsal video so cast members can review their blocking is an application of:','["a gym class", "a paper airplane", "technology in theatre", "a bake sale"]'::jsonb,2,'Video review helps rehearsals.','original'),
('117.213.b.3.D',3,'A sound cue that is triggered by a computer for a live show is an example of:','["manual labor only", "unplanned effects", "silent theatre", "technology in live theatre"]'::jsonb,3,'Cue software runs live shows.','original'),
('117.213.b.4.A',4,'A play about ordinary people during the Great Depression demonstrates theatre as a reflection of:','["life in a particular time and place", "a bus schedule", "a lunch menu", "a catalog"]'::jsonb,0,'Plays reflect their era.','original'),
('117.213.b.4.A',4,'A play set in a village in West Africa, using local stories and rhythms, reflects a:','["tax code", "particular culture", "grocery list", "weather report"]'::jsonb,1,'Theatre reflects cultures.','original'),
('117.213.b.4.B',4,'A student studies how a Greek chorus influenced modern ensemble acting. She is exploring:','["a video game", "a new snack", "theatre heritage", "a fashion trend"]'::jsonb,2,'Heritage includes historical influences.','original'),
('117.213.b.4.B',4,'Studying how a historic script has been preserved and performed for centuries explores:','["how seats are cleaned", "how tickets are sold", "how plays disappear", "how theatre heritage is kept alive"]'::jsonb,3,'Texts preserve heritage.','original'),
('117.213.b.4.C',4,'Comparing silent films to talking films, a student explores a key development in:','["film''s role in storytelling", "food service", "clothing design", "bus travel"]'::jsonb,0,'Sound changed film.','original'),
('117.213.b.4.C',4,'Streaming video lets a play reach audiences far from the theater. This shows the role of:','["ticket booths", "electronic media", "costumes", "props"]'::jsonb,1,'Electronic media expands reach.','original'),
('117.213.b.5.A',2,'At a live concert-style theatre piece, appropriate audience behavior includes:','["shouting during quiet scenes", "using phones", "responding politely and staying seated", "running onto stage"]'::jsonb,2,'Etiquette varies, but respect is constant.','original'),
('117.213.b.5.A',2,'At a children''s theatre show, audience etiquette includes:','["interrupting actors", "leaving trash", "walking around", "joining in only when invited"]'::jsonb,3,'Respect the show''s style.','original'),
('117.213.b.5.B',4,'When evaluating a performance, a student considers the artists'' intent, the structure of the story and:','["how effectively the production communicated its message", "the size of the lobby", "the price of snacks", "the weather"]'::jsonb,0,'Evaluation terms include intent, structure and effectiveness.','original'),
('117.213.b.5.B',4,'The first step in an evaluation process is often to:','["decide who won", "describe what you saw and heard", "ignore details", "guess the ending"]'::jsonb,1,'Describe first, then analyze and judge.','original'),
('117.213.b.5.C',3,'Camera work, editing and sound design are production elements that film shares with:','["a gym", "a bakery", "television", "a bank"]'::jsonb,2,'TV and film share media techniques.','original'),
('117.213.b.5.C',3,'Lighting, sound, costume and sets are production elements in:','["only mail delivery", "only farm work", "only retail", "theatre, film and television"]'::jsonb,3,'Production elements appear across media.','original'),
('117.213.b.5.D',3,'A stage manager, a lighting designer and a sound engineer all hold:','["theatre-related careers", "sports positions", "school rules", "unrelated hobbies"]'::jsonb,0,'They work in theatre vocations.','original'),
('117.213.b.5.D',3,'Someone who writes plays for a living has a career as a:','["banker", "playwright", "plumber", "pilot"]'::jsonb,1,'A playwright writes plays.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
